import { readdir, readFile, writeFile } from 'node:fs/promises'

const directory = new URL(
  '../../libs/gi/ui/src/util/teamOpt/rotation/kits/',
  import.meta.url
)
const files = await readdir(directory)
const kits = []
for (const file of files.sort()) {
  if (!file.endsWith('.ts') || file === 'index.ts') continue
  const source = await readFile(new URL(file, directory), 'utf8')
  if (/export const kit\s*:/.test(source)) kits.push(file.slice(0, -3))
}
const source = [
  '// Generated by tools/scripts/gen-rotation-kits.mjs. Regenerate after adding a kit.',
  "import type { CharacterKey } from '@genshin-optimizer/gi/consts'",
  "import type { KitModel } from '../types'",
  ...kits.map((key) => `import { kit as ${key} } from './${key}'`),
  '',
  "export { kitFramesInto } from './common'",
  '',
  '/** Character kits for the rotation simulator, by character key */',
  'export const kitModels: Partial<Record<CharacterKey, KitModel>> =',
  '  Object.fromEntries(',
  '    [',
  ...kits.map((key) => `      ${key},`),
  '    ].map((kit) => [kit.characterKey, kit])',
  '  )',
  '',
].join('\n')
await writeFile(new URL('index.ts', directory), source)
console.log(`Registered ${kits.length} rotation kits.`)
